"""Verify bounded delivery diagnostics generated by idle reporting."""

from __future__ import annotations

import asyncio
import io

import pytest

from cuprum import ScopeConfig, scoped
from cuprum._bounded_delivery import _DeliveryWorker
from cuprum._delivery_lifecycle import _queue_idle_diagnostic
from cuprum._stream_drain_state import _RelayDiagnostics
from cuprum.echo_events import EchoErrorCategory, EchoEvent, EchoStream, RelayFallback
from cuprum.echo_observation import observe_echo
from cuprum.sh import (
    BoundedDelivery,
    CommandResult,
    ExecutionContext,
    RunOutputOptions,
)
from cuprum.unittests.test_bounded_delivery_idle import (
    _pipeline,
    _run_target,
)
from tests.helpers.catalogue import build_python_catalogue_env

_IDLE_INTERVAL_S = 0.08


class _FailingIdleSink(io.StringIO):
    """Fail one selected operation made by an idle diagnostic."""

    def __init__(self, failure_site: str) -> None:
        """Select whether the idle write or flush fails."""
        super().__init__()
        self.failure_site = failure_site

    def write(self, text: str, /) -> int:
        """Fail a write when selected; otherwise retain the diagnostic."""
        if self.failure_site == "write":
            raise OSError
        return super().write(text)

    def flush(self) -> None:
        """Fail a flush when selected."""
        if self.failure_site == "flush":
            raise OSError


def test_queue_idle_diagnostic_reports_exact_stderr_source_bytes() -> None:
    """The shared idle route records its exact rejected stderr payload."""
    line = "idle line\n"
    sink = io.StringIO()
    worker = _DeliveryWorker(
        destinations={EchoStream.STDOUT: sink, EchoStream.STDERR: sink},
        max_queued_bytes=1,
    )
    diagnostics = _RelayDiagnostics()
    events: list[EchoEvent] = []

    try:
        with observe_echo(events.append):
            _queue_idle_diagnostic(worker, diagnostics, line)
    finally:
        worker.close(grace=0.1)

    expected_fallback = RelayFallback(
        stream=EchoStream.STDERR,
        error_category=EchoErrorCategory.DROPPED,
    )
    assert worker.queued_bytes == 0
    assert diagnostics.fallbacks == [expected_fallback]
    assert events == [
        EchoEvent(
            stream=EchoStream.STDERR,
            error_category=EchoErrorCategory.DROPPED,
            dropped_bytes=10,
        ),
    ]


@pytest.mark.parametrize("run_kind", ["command", "pipeline"])
@pytest.mark.parametrize("failure_site", ["write", "flush"])
def test_idle_delivery_failures_keep_successful_run_output(
    run_kind: str,
    failure_site: str,
) -> None:
    """Idle sink write and flush errors do not alter either run's result."""
    runtime = build_python_catalogue_env()
    python = runtime.builder
    script = "import time; time.sleep(0.4); print('captured', flush=True)"
    command = python("-c", script)
    target = command if run_kind == "command" else _pipeline(python, script)
    sink = _FailingIdleSink(failure_site)
    events: list[EchoEvent] = []
    output = RunOutputOptions(
        capture=True,
        echo=False,
        idle_after=_IDLE_INTERVAL_S,
        delivery=BoundedDelivery(max_queued_bytes=1024),
    )

    with (
        observe_echo(events.append),
        scoped(ScopeConfig(allowlist=frozenset([runtime.program]))),
    ):
        result = asyncio.run(
            _run_target(target, output, ExecutionContext(stderr_sink=sink)),
        )

    expected_fallback = RelayFallback(
        stream=EchoStream.STDERR,
        error_category=EchoErrorCategory.DELIVERY_ERROR,
    )
    if isinstance(result, CommandResult):
        assert result.exit_code == 0
        assert expected_fallback in result.relay_fallbacks
    else:
        assert [stage.exit_code for stage in result.stages] == [0, 0]
        assert expected_fallback in result.stages[-1].relay_fallbacks
    assert result.stdout == "captured\n"
    assert events
    assert events[0] == EchoEvent(
        EchoStream.STDERR,
        EchoErrorCategory.DELIVERY_ERROR,
    )
    assert all(event.stream is EchoStream.STDERR for event in events)
